def _spenta():
    try:
        from moduli.database import Database
        v = str(Database.get_config('patch_' + NUMERO, '1')).strip()
        if v in ('0', 'no', 'off'):
            traccia('spenta a mano (patch_' + NUMERO + ' = %s)' % v)
            return True
    except Exception as e:
        # ⛔ L'ECCEZIONE NON VALE "SPENTA": nel compilato l'import puo'
        #    fallire, e trattarlo come uno spegnimento aveva tenuto ferma la
        #    patch per ore senza un motivo visibile.
        traccia('non riesco a leggere la configurazione (%s): vado avanti lo stesso' % e)
    return False


def traccia(testo):
    try:
        import datetime
        import os
        d = os.path.join(os.environ.get('LOCALAPPDATA') or
                         os.path.expanduser('~'), 'KaraDom')
        os.makedirs(d, exist_ok=True)
        with open(os.path.join(d, 'patch033.log'), 'a', encoding='utf-8') as f:
            f.write('%s  %s' % (
                datetime.datetime.now().strftime('%Y-%m-%d %H:%M:%S'),
                testo) + chr(10))
    except Exception:
        pass


def apply():
    if _spenta():
        return False
    fatte = []

    # 0) il modulo che separa la voce: nel compilato non c'e', glielo si mette
    try:
        import sys as _s
        import types as _t
        import moduli as _pkg
        if _s.modules.get('moduli.devocalizza') is None:
            _m = _t.ModuleType('moduli.devocalizza')
            _m.__package__ = 'moduli'          # cosi' i suoi `from .x` funzionano
            _m.__file__ = '<patch_voce_devoc>'
            exec(compile(CODICE_DEVOC, '<patch_voce_devoc>', 'exec'), _m.__dict__)
            _s.modules['moduli.devocalizza'] = _m
            setattr(_pkg, 'devocalizza', _m)
            fatte.append('modello (messo)')
        else:
            # ⛔⛔ SI AGGIORNA LO STESSO. Prima qui si lasciava quello che
            #     c'era: ma le patch si applicano in fila (033, 034, 035...)
            #     e la PRIMA metteva il modulo vecchio — la nuova lo trovava
            #     e se lo teneva, e il roformer non arrivava mai.
            _m = _s.modules['moduli.devocalizza']
            exec(compile(CODICE_DEVOC, '<patch_voce_devoc>', 'exec'), _m.__dict__)
            fatte.append('modello (aggiornato)')
    except Exception as e:
        # non e' fatale: senza modello resta il metodo del centro, che suona
        traccia('modello NON messo: %s: %s' % (type(e).__name__, e))

    # 0-bis) il modulo del VOTO: anche questo nel compilato non c'e'
    try:
        import sys as _s
        import types as _t
        import moduli as _pkg
        _mv = _s.modules.get('moduli.votazione')
        if _mv is None:
            _mv = _t.ModuleType('moduli.votazione')
            _mv.__package__ = 'moduli'
            _mv.__file__ = '<patch_voto>'
        exec(compile(CODICE_VOTO, '<patch_voto>', 'exec'), _mv.__dict__)
        _s.modules['moduli.votazione'] = _mv
        setattr(_pkg, 'votazione', _mv)
        fatte.append('voto (motore)')
    except Exception as e:
        # senza il motore il resto del programma non cambia di una virgola
        traccia('voto NON messo: %s: %s' % (type(e).__name__, e))

    # 0-quater) il modulo del CATALOGO REMOTO
    try:
        import sys as _s2b
        import types as _t2b
        import moduli as _pkg2b
        _mc = _s2b.modules.get('moduli.catalogo_remoto')
        if _mc is None:
            _mc = _t2b.ModuleType('moduli.catalogo_remoto')
            _mc.__package__ = 'moduli'
            _mc.__file__ = '<patch_catalogo>'
        exec(compile(CODICE_CATALOGO, '<patch_catalogo>', 'exec'), _mc.__dict__)
        _s2b.modules['moduli.catalogo_remoto'] = _mc
        setattr(_pkg2b, 'catalogo_remoto', _mc)
        fatte.append('catalogo remoto')
    except Exception as e:
        traccia('catalogo remoto NON messo: %s: %s' % (type(e).__name__, e))

    # 0-quinquies) il CONTROLLO INCROCIATO dei nomi (LRCLIB + Genius)
    # ⚠️ DOPO catalogo_remoto: questo modulo lo importa in cima, e nel
    #    programma compilato non esiste finche' la patch non l'ha messo.
    try:
        import sys as _s2c
        import types as _t2c
        import moduli as _pkg2c
        _mk = _s2c.modules.get('moduli.catalogo_conferma')
        if _mk is None:
            _mk = _t2c.ModuleType('moduli.catalogo_conferma')
            _mk.__package__ = 'moduli'
            _mk.__file__ = '<patch_conferma>'
        exec(compile(CODICE_CONFERMA, '<patch_conferma>', 'exec'), _mk.__dict__)
        _s2c.modules['moduli.catalogo_conferma'] = _mk
        setattr(_pkg2c, 'catalogo_conferma', _mk)
        fatte.append('controllo incrociato')
    except Exception as e:
        traccia('controllo incrociato NON messo: %s: %s' % (type(e).__name__, e))

    # 0-sexies) I MIDI SCRITTI MALE SI APRONO LO STESSO
    # ⛔ Non si riscrive `extract_midi` (400 righe, lezione della 015): si
    #    rende tollerante il LETTORE, cosi' ne guadagnano tutti i punti che
    #    aprono un MIDI (testo, mixer, fluidsynth, esportazione) senza
    #    toccarne nessuno.
    # ⛔ IL FILE SUL DISCO NON SI TOCCA: si aggiusta una copia in memoria.
    try:
        import io as _io2
        import sys as _s2d
        import types as _t2d
        import moduli as _pkg2d
        _mr = _s2d.modules.get('moduli.midi_riparo')
        if _mr is None:
            _mr = _t2d.ModuleType('moduli.midi_riparo')
            _mr.__package__ = 'moduli'
            _mr.__file__ = '<patch_midi>'
        exec(compile(CODICE_MIDI, '<patch_midi>', 'exec'), _mr.__dict__)
        _s2d.modules['moduli.midi_riparo'] = _mr
        setattr(_pkg2d, 'midi_riparo', _mr)
        import mido as _mido
        if not getattr(_mido.MidiFile, '_karadom_tollerante', False):
            _Vecchia = _mido.MidiFile

            class _MidiFileTollerante(_Vecchia):
                _karadom_tollerante = True

                def __init__(self, filename=None, file=None, *a, **k):
                    try:
                        _Vecchia.__init__(self, filename, file, *a, **k)
                        return
                    except Exception as _primo:
                        if not filename:
                            raise
                        try:
                            with open(filename, 'rb') as _f:
                                _grezzo = _f.read()
                            _ok, _quanti = _mr.aggiusta_i_byte(_grezzo)
                            if _ok == _grezzo:
                                raise _primo
                            _Vecchia.__init__(self, None, _io2.BytesIO(_ok),
                                              *a, **k)
                        except Exception:
                            raise _primo

            _mido.MidiFile = _MidiFileTollerante
            try:
                import mido.midifiles.midifiles as _mm
                _mm.MidiFile = _MidiFileTollerante
            except Exception:
                pass
        fatte.append('midi scritti male')
    except Exception as e:
        traccia('midi scritti male NON messo: %s: %s' % (type(e).__name__, e))

    # 0-ter) il tab "Voto" dentro la finestra delle Opzioni
    try:
        import sys as _s3
        mo = _s3.modules.get('moduli.opzioni')
        if mo is not None:
            cls = None
            for _n in dir(mo):
                _o = getattr(mo, _n)
                if isinstance(_o, type) and hasattr(_o, 'create_widgets') and                         hasattr(_o, 'create_tab_generale'):
                    cls = _o
                    break
            if cls is not None:
                _sp = {}
                exec(compile(CODICE_OPZ, '<patch_voto_opz>', 'exec'),
                     mo.__dict__, _sp)
                for _n in NOMI_OPZ:
                    if _n in _sp:
                        _fn = _sp[_n]
                        if _n in NOMI_OPZ_STATICI:
                            _fn = staticmethod(_fn)
                        setattr(cls, _n, _fn)
                # l'elenco delle voci che scrive il programma da se'
                try:
                    cls.CONFIG_DI_SERVIZIO = CONFIG_SERVIZIO
                except Exception:
                    pass

                # ⛔⛔ IL TAB SI AGGIUNGE, NON SI RISCRIVE `create_widgets`:
                #     quella del sorgente chiama metodi che nell'exe non ci
                #     sono (`_segna_tempo`) e le Opzioni si fermavano con
                #     "object has no attribute". Qui si lascia fare tutto a
                #     lei e alla fine si appende il tab in fondo al notebook.
                if CODICE_VOTO and not getattr(cls, '_voto_gia_appeso', False):
                    _vecchia = cls.create_widgets

                    def _con_voto(self, *a, **k):
                        _r = _vecchia(self, *a, **k)
                        try:
                            import tkinter.ttk as _ttk

                            def _cerca(w):
                                if isinstance(w, _ttk.Notebook):
                                    return w
                                for c in w.winfo_children():
                                    t = _cerca(c)
                                    if t is not None:
                                        return t
                                return None
                            nb = _cerca(getattr(self, 'window', None) or self)
                            if nb is not None:
                                # ⭐ la finestra dell'exe e' piu' stretta: la
                                #    si allarga qui, il costruttore non si
                                #    puo' patchare (chiama roba che non c'e')
                                try:
                                    w = self.window
                                    w.update_idletasks()
                                    if w.winfo_width() < 1000:
                                        # ⛔⛔ l'altezza puo' solo CRESCERE: a
                                        #     finestra ancora nascosta Tk
                                        #     risponde 1 pixel, e la finestra
                                        #     veniva fuori schiacciata
                                        h = max(w.winfo_height() or 0,
                                                w.winfo_reqheight() or 0, 800)
                                        sw = w.winfo_screenwidth()
                                        sh = w.winfo_screenheight()
                                        h = min(h, sh - 80)
                                        nuova = min(1050, sw - 60)
                                        w.geometry('%dx%d+%d+%d' % (
                                            nuova, h, max(0, (sw - nuova) // 2),
                                            max(0, w.winfo_y())))
                                except Exception:
                                    pass
                                gia = [nb.tab(i, 'text') for i in range(nb.index('end'))]
                                if not any('Voto' in str(x) for x in gia):
                                    self.create_tab_voto(nb)
                        except Exception:
                            pass          # il tab in meno non ferma le Opzioni
                        return _r
                    cls.create_widgets = _con_voto
                    cls._voto_gia_appeso = True
                fatte.append('tab del voto nelle Opzioni')
    except Exception as e:
        traccia('tab del voto NON messo: %s: %s' % (type(e).__name__, e))

    # ⛔ Via il vecchio filtro dentro il motore audio, se una versione
    #    precedente l'aveva agganciato: era codice Python dentro il thread del
    #    suono e bloccava il programma.
    try:
        import sys as _s2
        mb = _s2.modules.get('moduli.bass_engine')
        if mb and hasattr(mb, 'BassEngine'):
            for n in ('set_voce', '_togli_dsp_voce', '_aggancia_dsp_voce'):
                if n in mb.BassEngine.__dict__:
                    delattr(mb.BassEngine, n)
    except Exception:
        pass

    # ⛔ Via la voce "Avvia DOM SVC (Camera Controller)" dal menu Strumenti.
    #    Nel sorgente non c'e' piu' (resta solo nei backup vecchi), ma
    #    l'eseguibile in uso e' precedente e continua a mostrarla: quel codice
    #    li' dentro e' gia' compilato e non lo si tocca modificando un file.
    #    Si mette un filtro su chi aggiunge le voci ai menu.
    try:
        import tkinter as _tk
        _agg = _tk.Menu.add_command
        if not getattr(_agg, '_voce_avvolta', False):
            def _add_command(self, cnf={}, **kw):
                try:
                    testo = str(kw.get('label') or (cnf or {}).get('label') or '')
                    if 'DOM SVC' in testo:
                        return None
                except Exception:
                    pass
                return _agg(self, cnf, **kw)
            _add_command._voce_avvolta = True
            _tk.Menu.add_command = _add_command
        fatte.append('voce DOM SVC tolta')
    except Exception as e:
        traccia('voce DOM SVC NON tolta: %s: %s' % (type(e).__name__, e))

    # ⛔ E via anche il MOTORE del DOM SVC, non solo la sua voce di menu: il
    #    programma compilato lancia `adb` all'avvio per vedere se c'e' un
    #    telefono collegato, e lascia in giro adb.log. Togliere la voce non
    #    bastava — si vedeva dal file che continuava a nascere.
    #    Gli si fa credere che adb non ci sia: e' la stessa strada che il
    #    programma prevede gia' ("SKV disabilitato: dipendenze non trovate").
    try:
        import os as _os2
        import subprocess as _sp
        _Popen = _sp.Popen
        if not getattr(_Popen, '_voce_avvolta', False):
            def _popen_senza_adb(args, *a, **k):
                try:
                    primo = args[0] if isinstance(args, (list, tuple)) and args else args
                    if _os2.path.basename(str(primo)).lower() in (
                            'adb.exe', 'adb', 'fastboot.exe'):
                        raise FileNotFoundError(
                            2, 'adb spento da patch_' + NUMERO, str(primo))
                except FileNotFoundError:
                    raise
                except Exception:
                    pass
                return _Popen(args, *a, **k)
            _popen_senza_adb._voce_avvolta = True
            _sp.Popen = _popen_senza_adb
        fatte.append('adb del DOM SVC spento')
    except Exception as e:
        traccia('adb NON spento: %s: %s' % (type(e).__name__, e))

    # Le scritte nuove tradotte. ⛔ Devono viaggiare CON LA PATCH: en.json e'
    # un file di dati e la patch porta solo codice, quindi in inglese il tasto
    # resterebbe in italiano fino alla ricompilazione.
    try:
        import moduli.i18n as mi
        if isinstance(getattr(mi, '_translations', None), dict):
            mi._translations.update(TRADUZIONI)
        _carica = getattr(mi, 'load_language', None)
        if _carica is not None and not getattr(_carica, '_voce_avvolta', False):
            def _carica_e_aggiungi(lang, _o=_carica):
                r = _o(lang)
                try:
                    if isinstance(mi._translations, dict):
                        mi._translations.update(TRADUZIONI)
                except Exception:
                    pass
                return r
            _carica_e_aggiungi._voce_avvolta = True
            mi.load_language = _carica_e_aggiungi
        fatte.append('scritte tradotte')
    except Exception as e:
        traccia('traduzioni NON messe: %s: %s' % (type(e).__name__, e))

    try:
        # le dipendenze si scaricano in sottofondo, non tenendo fermo il
        # programma: adesso fra quelle c'e' anche il motore che separa la voce
        import moduli.dep_sync as md
        sp = md.__dict__
        exec(compile(CODICE_DEP, "<patch_voce_dep>", "exec"), sp)
        md.completa_mancanti = sp['completa_mancanti']
        md._completa_mancanti_ora = sp['_completa_mancanti_ora']
        fatte.append('dipendenze in sottofondo')
    except Exception as e:
        traccia('dipendenze NON sistemate: %s: %s' % (type(e).__name__, e))

    try:
        import moduli.system as ms
        sp = ms.__dict__
        exec(compile(CODICE_SYS, "<patch_voce_sys>", "exec"), sp)
        for n in NOMI_SYS:
            setattr(ms.KaraokeMonitorSystem, n, sp[n])
        # ⚠️ i valori scritti nella classe: `prendi` copia solo le funzioni,
        #    e senza questi il filtro userebbe i ripieghi scritti a mano
        ms.KaraokeMonitorSystem.TAGLIO_GRAVE = 120
        ms.KaraokeMonitorSystem.TAGLIO_ARIA = 12000
        ms.KaraokeMonitorSystem.RIPIDITA = 2
        fatte.append('comando')
    except Exception as e:
        traccia('comando NON agganciato: %s: %s' % (type(e).__name__, e))
        return False

    try:
        import moduli.yt2mp3 as my
        C = my.YoutubePanel
        sp = my.__dict__
        exec(compile(CODICE_YT, "<patch_voce_yt>", "exec"), sp)
        for n in NOMI_YT:
            setattr(C, n, sp[n])
        if getattr(C, 'btn_karaoke', None) is None:
            C.btn_karaoke = None
        fatte.append('barra youtube')
    except Exception as e:
        traccia('barra youtube NON agganciata: %s: %s' % (type(e).__name__, e))

    try:
        # ⭐ Lo splash della prova: sotto il seriale compaiono impronta
        #    hardware, versione e patch attive. Serve all'assistenza al
        #    telefono — prima l'impronta non si vedeva da nessuna parte.
        # ⚠️ `_riga_tecnica_di` sta nel MODULO, `_crea_contenuto` e' un metodo
        #    della classe `SplashScreen`: si attaccano in due posti diversi.
        import moduli.splash as msp
        ssp = msp.__dict__
        exec(compile(CODICE_SPLASH, "<patch_voce_splash>", "exec"), ssp)
        for n in NOMI_SPLASH_MOD:
            setattr(msp, n, ssp[n])
        for n in NOMI_SPLASH_CLS:
            setattr(msp.SplashScreen, n, ssp[n])
        fatte.append('splash con impronta e patch')
    except Exception as e:
        traccia('splash NON agganciato: %s: %s' % (type(e).__name__, e))

    try:
        import moduli.libreria as ml
        sp = ml.__dict__
        exec(compile(CODICE_LIB, "<patch_voce_lib>", "exec"), sp)
        for n in NOMI_LIB:
            setattr(ml.LibreriaSlider, n, sp[n])
        # ⛔⛔ QUI C'ERA UNA PULIZIA CHE STACCAVA `_voce_su_giu`,
        #    `_voce_disarma`, `_voce_nuovo_brano` e `_voce_brano_scelto`.
        #    Aveva senso quando il tasto non c'era piu'. Col tasto rimesso
        #    faceva questo: il ciclo qui sopra le attaccava, e due righe dopo
        #    questa le staccava — quindi `create_slider` chiamava un metodo
        #    che non esisteva piu' e il programma MORIVA ALL'AVVIO:
        #        CRASH: 'LibreriaSlider' object has no attribute '_voce_su_giu'
        #    Se un domani il tasto si toglie di nuovo, si toglie da `LIB`:
        #    cosi' non vengono nemmeno attaccate, invece di attaccarle e
        #    staccarle.
        # Appena si SCEGLIE un brano, se il tasto e' gia' armato la
        # preparazione comincia subito.
        # ⭐ La funzione originale non si riscrive: le si mette un cappotto
        #    intorno e la si chiama (come nella 017).
        C = ml.LibreriaSlider
        for n in ('seleziona_suggerimento', 'seleziona_suggerimento_auto'):
            orig = getattr(C, n, None)
            if orig is None or getattr(orig, '_voce_avvolta', False):
                continue

            def cappotto(self, event=None, _orig=orig):
                r = _orig(self, event)
                try:
                    self._voce_nuovo_brano(
                        getattr(self, 'brano_selezionato_path', None))
                except Exception:
                    pass
                return r

            cappotto._voce_avvolta = True
            setattr(C, n, cappotto)
        fatte.append('tasto nella barra')
    except Exception as e:
        traccia('barra libreria NON agganciata: %s: %s' % (type(e).__name__, e))

    traccia('AGGANCIATA: ' + ', '.join(fatte))
    print("patch " + NUMERO + ": si puo' togliere la voce dal brano")
    return True


def revert():
    print("patch " + NUMERO + ": si toglie riavviando")
    return True


try:
    apply()
except Exception:
    pass
